import { type SQL, sql } from "drizzle-orm";
import { type AnyPgColumn, customType, uuid } from "drizzle-orm/pg-core";

/**
 * Column patterns every table reuses — PLAN.md §5.2.
 *
 * These exist so the rules stated once in the plan are applied by construction rather than
 * by each table's author remembering them. The audit quartet lives in `entity.ts` instead,
 * because it references the entity table and would otherwise close an import cycle.
 */

/**
 * Primary keys are UUIDv7, generated by the database.
 *
 * Time-ordered, so inserts append to the right of the index instead of scattering across it
 * the way v4 does, and so `ORDER BY id` *is* creation order — which comment ordering (§2.8)
 * depends on. Generating in the database also means an id exists for every row however it
 * was written, a psql session during a migration included.
 *
 * This is what sets the Postgres 18 floor; `db/version.ts` checks it at startup.
 */
export const primaryKeyColumn = () =>
	uuid().primaryKey().default(sql`uuidv7()`);

/**
 * Postgres `daterange`, the storage for every archival date (PLAN.md §2.5).
 *
 * A rough date denotes a *span*, so a range is the honest column type: the timeline filters
 * with a GiST-indexed `&&` overlap against the selected window, which is both cheaper and
 * more truthful than comparing bare timestamps.
 *
 * Values move as Postgres' own literal — `[1920-01-01,1930-01-01)`, lower bound inclusive
 * and upper exclusive. `shared`'s spans are inclusive at both ends, so the two are converted
 * for each other rather than assumed compatible; see `../rough-date-range.ts`.
 */
export const daterange = customType<{ data: string; driverData: string }>({
	dataType: () => "daterange",
});

/**
 * A per-row text-search configuration (PLAN.md §4.3).
 *
 * The configuration name is a *setting*, never a constant: a host carrying the Hunspell
 * dictionary gets compound splitting, one without it degrades to stemming. Storing it per
 * row is also what lets a German and an English content row sit in the same table and each
 * be indexed correctly — and the query must pass the matching configuration explicitly or
 * the GIN index is not used.
 */
export const regconfig = customType<{ data: string; driverData: string }>({
	dataType: () => "regconfig",
});

export const tsvector = customType<{ data: string; driverData: string }>({
	dataType: () => "tsvector",
});

/**
 * The SQL for a `DateOrInterval`'s generated extent column — the hull of both ends, which
 * is what the timeline's `&&` overlap test runs against.
 *
 * `coalesce` is what makes a lone date work: with no end there is nothing to take a hull of,
 * so the extent is the start's own span.
 */
export const extentExpression = (start: AnyPgColumn, end: AnyPgColumn): SQL =>
	sql`range_merge(${start}, coalesce(${end}, ${start}))`;

/**
 * The SQL for a content row's generated `tsvector` — PLAN.md §4.3.
 *
 * Weighted so a name outranks an abstract: a search for "Kirche" should surface the place
 * called Kirche before every story that mentions one.
 */
export const searchVectorExpression = (
	config: AnyPgColumn,
	name: AnyPgColumn,
	abstract: AnyPgColumn,
): SQL =>
	sql`setweight(to_tsvector(${config}, coalesce(${name}, '')), 'A') || setweight(to_tsvector(${config}, coalesce(${abstract}, '')), 'B')`;
